const auth=useAuthStore();const full=['agent:view','agent:task:view','agent:manage','agent:task:operate'];auth.permissions=full
const selected=ref('cli'), mode=ref('cli'), second=ref(false), visible=ref(true), refreshed=ref(0), ready=ref(true), version=ref(11), status=ref('WAITING_RESOURCE')
const run=computed(()=>({id:second.value?'run-two':'run-one',taskId:'task-fixture',agentId:'agent-fixture',status:status.value,stepCount:4,elapsedMillis:45000,cancelRequested:mode.value==='cancel',resultText:null,errorMessage:'本地样本：原执行回执缺失',retryAllowed:false,version:version.value,createdAt:'2026-11-04T06:00:00',updatedAt:'2026-11-04T06:10:00'}))
