</script>
<template><main><aside><strong>本地样本验证 · 不连接业务系统</strong><label>样本响应 <select v-model="selected" aria-label="样本响应" @change="setMode"><option value="cli">CLI 与工具均未知</option><option value="api">API 未知</option><option value="alive">CLI 仍存活</option><option value="known">实际回执已到齐</option><option value="cancel">已请求取消</option><option value="error">读取失败</option><option value="delay">读取延迟12秒</option><option value="post-delay">提交延迟12秒</option><option value="lost">已保存但响应丢失</option></select></label><button @click="second=!second">切换运行</button><button @click="togglePermission">切换管理权限</button><button @click="visible=!visible">切换页面激活</button><span>{{ready?'已应用':'应用中'}}：{{mode}} · {{run.id}} · 已刷新 {{refreshed}} 次 · {{status}}</span></aside><h2>Agent 运行人工核对</h2><KeepAlive><AgentRunReconciliationPanel v-if="visible" :run="run" @refresh="refresh" /></KeepAlive></main></template>
